 container.addEventListener('keydown',keyboard);container.addEventListener('click',click);container.addEventListener('input',change);container.addEventListener('change',change);container.addEventListener('compositionstart',startComposition);container.addEventListener('compositionend',endComposition);const unsubscribe=controller.subscribe(render);render();
 return {refresh:render,dispose(){if(disposed)return;remember();disposed=true;clearTimeout(timer);clearTimeout(eraTimer);unsubscribe();container.removeEventListener('keydown',keyboard);container.removeEventListener('click',click);container.removeEventListener('input',change);container.removeEventListener('change',change);container.removeEventListener('compositionstart',startComposition);container.removeEventListener('compositionend',endComposition);container.innerHTML='';}};
